const money=(v,c='GHS')=>{const n=Number(v)||0;try{return new Intl.NumberFormat('en-GH',{style:'currency',currency:c,minimumFractionDigits:2}).format(n)}catch{return `${c} ${n.toFixed(2)}`}};
